function validate(input) {
  const [{ EmployeeShifts = [] }] = input;
  const seen = new Set(), time = /^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$/;
  for (const [id, start, end] of EmployeeShifts) {
    if (id === null || start === null || end === null) return 'EmployeeShifts rows may not contain null.';
    if (!time.test(start) || !time.test(end)) return `Employee ${id} has a time that is not HH:MM:SS.`;
    if (start >= end) return `Employee ${id}'s shift at ${start} must end after it starts.`;
    const key = `${id}|${start}`;
    if (seen.has(key)) return `Employee ${id} has two shifts starting at ${start}.`;
    seen.add(key);
  }
  return null;
}

