function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const clock = (minutes) => `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}:00`;
  const count = small ? pick(9) : 2000;
  const people = small ? 1 + pick(4) : 200;
  // Small cases start on whole hours and last whole hours, so touching shifts are common.
  const step = small ? 60 : 15, slots = small ? 9 : 81, first = small ? 8 * 60 : 0;
  const used = new Set(), rows = [];
  for (let tries = 0; rows.length < count && tries < count * 20; tries++) {
    const id = small ? [1, 2, 3, 7][pick(people)] : 1 + pick(people);
    const start = first + step * pick(slots);
    const key = `${id}|${start}`;
    if (used.has(key)) continue;
    used.add(key);
    const length = small ? 60 * (1 + pick(4)) : 30 * (1 + pick(12));
    rows.push([id, clock(start), clock(Math.min(start + length, 23 * 60 + 59))]);
  }
  return [{ EmployeeShifts: rows }];
}
